<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {onBeforeRouteLeave,useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,message} from '../api/client'
import {loadBranding,formatDate} from '../ui/branding'
import SystemStatus from '../components/SystemStatus.vue'
import {useAuth} from '../stores/auth'
import {settingsTab,isConfigurationTab,legacySettingsDestination} from '../ui/settingsNavigation'
import {defineAsyncComponent} from 'vue'
const SystemOperations=defineAsyncComponent(()=>import('./SystemOperations.vue'))
const auth=useAuth(),route=useRoute(),router=useRouter(),isSuper=computed(()=>auth.user?.role==='super_admin')
const operationsReady=import.meta.env.VITE_OPERATIONS_READY!=='false'
import {settingsTabs,settingsPayload,acceptSaved,copy,equal} from '../ui/settingsDraft'
const form=reactive<any>({}),ready=ref(false),loading=ref(false),saving=ref(false),error=ref(''),tab=ref(settingsTab(auth.user?.role,route.query.tab)),rules=ref('')
const vectorOptions=ref<any[]>([]),testLoading=ref(false),esStatus=ref<any>({}),vectorResult=ref<any>(null)
const baseline=ref<any>(null)
const dirtyTabs=computed(()=>baseline.value?Object.keys(settingsTabs).filter(key=>!equal(settingsPayload(form,rules.value,key),settingsPayload(baseline.value,baseline.value.logging.redaction_rules.join('\n'),key))):[])
const currentDirty=computed(()=>dirtyTabs.value.includes(tab.value))
const pending=computed(()=>dirtyTabs.value.length>0)
async function confirmDiscard(){try{await ElMessageBox.confirm('有尚未保存的更改，继续将放弃这些更改。','未保存更改',{confirmButtonText:'放弃更改',cancelButtonText:'继续编辑',type:'warning'});return true}catch{return false}}
async function reload(){if(pending.value&&!await confirmDiscard())return;await load()}
function resetCurrent(){const fields=settingsPayload(baseline.value,baseline.value.logging.redaction_rules.join('\n'),tab.value);if(tab.value==='brand')fields.basic={...fields.basic,logo:baseline.value.basic.logo,icon:baseline.value.basic.icon};for(const [section,values] of Object.entries(fields))for(const key of Object.keys(values))form[section][key]=copy(baseline.value[section][key]);if(tab.value==='basic')rules.value=baseline.value.logging.redaction_rules.join('\n')}
function beforeUnload(event:BeforeUnloadEvent){if(pending.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(async()=>saving.value?false:!pending.value||await confirmDiscard())
const requests=new Set<AbortController>()
const auxiliaryReady=reactive<Record<string,boolean>>({})
const auxiliaryLoading=reactive<Record<string,boolean>>({})
const auxiliaryError=reactive<Record<string,string>>({})
let disposed=false,generation=0
onBeforeUnmount(()=>{disposed=true;generation++;for(const request of requests)request.abort();window.removeEventListener('beforeunload',beforeUnload)})
const providers=computed(()=>[...new Map(vectorOptions.value.map(o=>[o.provider_id,{id:o.provider_id,name:o.provider_name}])).values()])
const vectorModels=computed(()=>vectorOptions.value.filter(o=>o.provider_id===form.vector?.provider_id))
const gatewayFields=[['max_concurrency','最大并发','同时执行的请求数量上限',1,100000,'个请求'],['queue_size','队列大小','达到并发上限时允许等待的请求数量',0,100000,'个请求'],['queue_timeout','队列等待超时','超过等待时间后返回超时',1,3600,'秒'],['nonstream_timeout','非流式请求超时','非流式调用及上游响应头等待上限',1,600,'秒'],['stream_idle_timeout','流式空闲超时','连续无数据返回时关闭流式连接',1,3600,'秒'],['max_body_bytes','最大请求体','超过上限的请求会被拒绝，最高 10 MiB（10,485,760 字节）',1024,10485760,'字节']] as const
const commonTimezones:Record<string,string>={'Asia/Shanghai':'北京时间 · Asia/Shanghai（UTC+08:00）','UTC':'协调世界时 · UTC（UTC+00:00）','Asia/Hong_Kong':'香港 · Asia/Hong_Kong（UTC+08:00）','Asia/Taipei':'台北 · Asia/Taipei（UTC+08:00）','Asia/Singapore':'新加坡 · Asia/Singapore（UTC+08:00）','Asia/Tokyo':'东京 · Asia/Tokyo（UTC+09:00）','Asia/Seoul':'首尔 · Asia/Seoul（UTC+09:00）','Asia/Kolkata':'印度 · Asia/Kolkata（UTC+05:30）','Europe/London':'伦敦 · Europe/London','Europe/Paris':'巴黎 · Europe/Paris','America/New_York':'纽约 · America/New_York','America/Los_Angeles':'洛杉矶 · America/Los_Angeles','Australia/Sydney':'悉尼 · Australia/Sydney'}
const timezoneApi=Intl as typeof Intl & {supportedValuesOf?:(key:string)=>string[]}
const availableTimezones=timezoneApi.supportedValuesOf?.('timeZone')||[]
const timezoneOptions=computed(()=>[...new Set([...Object.keys(commonTimezones),form.basic?.timezone,...availableTimezones].filter((zone):zone is string=>typeof zone==='string'&&!!zone))].map(value=>({value,label:commonTimezones[value]||value})))
async function load(){
  if(loading.value)return
  const version=++generation,request=new AbortController();requests.add(request)
  for(const previous of requests)if(previous!==request)previous.abort()
  for(const key of ['vector','elasticsearch']){auxiliaryReady[key]=false;auxiliaryLoading[key]=false;auxiliaryError[key]=''}
  loading.value=true;error.value=''
  try{
    const s=await api.get('/admin/settings',{params:{include_assets:false},signal:request.signal,timeout:15000})
    if(disposed||version!==generation)return
    Object.assign(form,s.data.data);baseline.value=copy(s.data.data);savedVector.value=copy(form.vector);rules.value=form.logging.redaction_rules.join('\n')
    ready.value=true;vectorResult.value=null
  }catch(e){if(!request.signal.aborted)error.value=message(e)}finally{requests.delete(request);if(version===generation){loading.value=false;if(!error.value&&ready.value)void loadAuxiliary(tab.value)}}
}
async function loadAuxiliary(key:string,force=false){
  if(!ready.value||loading.value||disposed||!['vector','elasticsearch'].includes(key)||auxiliaryLoading[key]||auxiliaryReady[key]&&!force)return
  const version=generation,request=new AbortController();requests.add(request);auxiliaryLoading[key]=true;auxiliaryError[key]='';if(key==='elasticsearch'&&!auxiliaryReady[key])esStatus.value={unavailable:true}
  const options={signal:request.signal,timeout:15000}
  try{
    if(key==='vector'){
      const v=await api.get('/admin/settings/vector-options',options)
      if(disposed||version!==generation)return
      vectorOptions.value=v.data.data
    }else{
      const s=await api.get('/admin/settings/elasticsearch/status',options)
      if(disposed||version!==generation)return
      esStatus.value=s.data.data
    }
    auxiliaryReady[key]=true
  }catch(e){if(!request.signal.aborted&&version===generation){auxiliaryError[key]=message(e);if(key==='elasticsearch')esStatus.value={unavailable:true}}}finally{requests.delete(request);if(version===generation)auxiliaryLoading[key]=false}
}
async function loadEsStatus(){await loadAuxiliary('elasticsearch',true)}
watch(tab,key=>{void loadAuxiliary(key);if(route.query.tab!==key)void router.replace({query:{...route.query,tab:key}})})
watch(()=>route.query.tab,value=>{const target=legacySettingsDestination(value);if(target){void router.replace(target);return}tab.value=settingsTab(auth.user?.role,value)})
async function save(){
  if(saving.value||!currentDirty.value)return
  const savingTab=tab.value,sent=copy(settingsPayload(form,rules.value,savingTab)),sentRules=rules.value
  if(savingTab==='basic'){const address=sent.basic.public_api_base_url.trim();if(address&&!address.replace(/\/$/,'').endsWith('/v1')){ElMessage.error('接入地址须以 /v1 结尾');return}form.basic.public_api_base_url=sent.basic.public_api_base_url=address}
  saving.value=true
  try{
    if(savingTab==='vector')await ElMessageBox.confirm('更换共享向量服务会使已有路由和审核样本向量失效。保存后需手动重建，重建可能产生用量和费用。','保存向量服务',{confirmButtonText:'保存',cancelButtonText:'取消'})
    const saved=(await api.patch('/admin/settings',{revision:form.revision,...sent},{params:{include_assets:false}})).data.data
    acceptSaved(form,baseline.value,sent,saved)
    if(savingTab==='basic'&&rules.value===sentRules)rules.value=saved.logging.redaction_rules.join('\n')
    if(savingTab==='vector'){savedVector.value=copy(saved.vector);vectorResult.value=null}
    ElMessage.success(settingsTabs[savingTab]+'已保存')
    // Auxiliary refresh failure must not report an already committed save as failed.
    if(savingTab==='brand'||savingTab==='basic')try{await loadBranding()}catch{ElMessage.warning('配置已保存，品牌显示请刷新页面更新')}
    if(savingTab==='elasticsearch')void loadEsStatus()
  }catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}finally{saving.value=false}
}
const savedVector=ref<any>({})
async function testVector(){if(testLoading.value||saving.value)return;testLoading.value=true;let request:AbortController|undefined;try{await ElMessageBox.confirm('使用已保存的账号和模型发起一次短文本向量调用，可能产生费用。','测试向量服务',{confirmButtonText:'测试',cancelButtonText:'取消'});if(disposed)return;request=new AbortController();requests.add(request);const revision=form.revision;const result=(await api.post('/admin/settings/vector-test',{consent:true,revision},{signal:request.signal,timeout:135000})).data.data;if(!disposed&&revision===form.revision){vectorResult.value=result;ElMessage.success('向量服务可用')}}catch(e){if(!disposed&&!request?.signal.aborted&&e!=='cancel'&&e!=='close')ElMessage.error(message(e))}finally{if(request)requests.delete(request);testLoading.value=false}}
async function testEs(){if(testLoading.value||saving.value)return;testLoading.value=true;const request=new AbortController();requests.add(request);try{const d=(await api.post('/admin/settings/elasticsearch/test',undefined,{signal:request.signal,timeout:15000})).data.data;if(!disposed){ElMessage.success('连接成功，Elasticsearch '+d.version);await loadEsStatus()}}catch(e){if(!disposed&&!request.signal.aborted)ElMessage.error(message(e))}finally{requests.delete(request);testLoading.value=false}}
function image(event:Event,key:'logo'|'icon'){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;input.value='';if(file.type!=='image/png'||file.size>256*1024){ElMessage.error('请选择不超过256KiB的PNG图片');return}const version=generation,reader=new FileReader();reader.onload=()=>{if(!disposed&&version===generation)form.basic[key]=String(reader.result)};reader.onerror=()=>{if(!disposed)ElMessage.error('图片读取失败，请重新选择')};reader.readAsDataURL(file)}
onMounted(async()=>{const target=legacySettingsDestination(route.query.tab);if(target){await router.replace(target);return}window.addEventListener('beforeunload',beforeUnload);if(isSuper.value)await load();else ready.value=true})
</script>
<template>
<PageHeader title="系统设置"><el-button v-if="isSuper&&isConfigurationTab(tab)&&tab!=='status'" :disabled="saving||testLoading" :loading="loading" @click="reload">重新加载</el-button></PageHeader>
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<el-skeleton v-if="!ready&&loading" :rows="8" animated/>
<section v-if="ready" class="panel settings-panel" v-loading="loading"><el-alert v-if="auxiliaryError[tab]" :title="auxiliaryError[tab]" type="error" :closable="false"><el-button link type="primary" @click="loadAuxiliary(tab,true)">重新加载当前页签</el-button></el-alert><el-tabs v-model="tab" :before-leave="()=>!saving">
<el-tab-pane v-if="isSuper" label="基础与品牌" name="brand" lazy><el-form label-position="top"><el-form-item label="系统名称"><el-input v-model="form.basic.system_name" maxlength="80"/></el-form-item><div class="settings-grid"><el-form-item v-for="key in (['logo','icon'] as const)" :key="key" :label="key==='logo'?'系统Logo':'浏览器Icon'"><img v-if="form.basic[key]" :src="form.basic[key]" class="brand-preview"/><input type="file" accept="image/png" @change="image($event,key)"/><el-button text @click="form.basic[key]=''">清除</el-button></el-form-item></div><el-form-item label="系统URL"><el-input v-model="form.basic.system_url" placeholder="留空使用当前网站地址"/></el-form-item><el-form-item label="语言"><el-select v-model="form.basic.language"><el-option label="简体中文" value="zh-CN"/></el-select></el-form-item><el-form-item label="显示时区"><el-select v-model="form.basic.timezone" filterable placeholder="选择显示时区，可搜索城市或 IANA 时区" class="timezone-select"><el-option v-for="zone in timezoneOptions" :key="zone.value" :label="zone.label" :value="zone.value"/></el-select></el-form-item><p class="muted">显示时间使用此时区；Token配额周期与统计分桶仍按北京时间计算。</p></el-form></el-tab-pane>
<el-tab-pane v-if="isSuper" label="基础设置" name="basic" lazy><div class="section-heading"><h2>基础设置</h2><p>管理对外接入地址、调用日志留存和协议适配。</p></div><el-form label-position="top" class="settings-form"><el-form-item label="接入地址（OpenAI Base URL）"><el-input v-model="form.basic.public_api_base_url" placeholder="http://网关地址:端口/v1"/><p class="field-hint">支持 HTTP / HTTPS，以 /v1 结尾；留空使用当前站点地址 /v1。</p></el-form-item><el-form-item label="日志保留天数"><el-input-number v-model="form.logging.retention_days" :min="1" :max="3650" :precision="0"/><p class="field-hint">调用、决策与审核日志到期分批清理；用量汇总和管理审计长期保留。已有 366 天及以上配置继续兼容。</p></el-form-item><div class="setting-line"><div><strong>协议转换</strong><p>优先原生协议；开启后允许 Chat Completions 与 Anthropic Messages 相互转换。</p></div><el-switch v-model="form.gateway.protocol_conversion" aria-label="协议转换"/></div><p class="field-hint">协议专属字段、工具和多模态内容可能无法安全转换；Responses 使用原生协议。</p><el-divider/><h3>正文与脱敏</h3><el-alert v-if="form.logging.save_request_body||form.logging.save_response_body" type="warning" :closable="false" title="已开启业务正文留存。内置脱敏不能识别所有个人信息和业务秘密，请补充实际脱敏规则，并按业务要求确认保留期、日志访问及备份范围。关闭正文记录只影响后续请求，不删除已有记录。"/><div class="setting-line"><div><strong>保存请求正文</strong><p>仅保存脱敏预览，最多 16 KiB。</p></div><el-switch v-model="form.logging.save_request_body" aria-label="保存请求正文"/></div><div class="setting-line"><div><strong>保存响应正文</strong><p>流式响应保存有限事件预览。</p></div><el-switch v-model="form.logging.save_response_body" aria-label="保存响应正文"/></div><el-form-item label="附加脱敏正则"><el-input v-model="rules" type="textarea" :rows="4" placeholder="每行一条，最多 20 条"/></el-form-item><p class="field-hint">认证头不保存，密码与密钥字段始终脱敏。开启正文记录后会保存客户输入和模型输出。</p></el-form></el-tab-pane>
<el-tab-pane v-if="isSuper" label="性能设置" name="performance" lazy><div class="section-heading"><h2>性能设置</h2><p>限制并发、队列和超时，控制网关资源占用。</p></div><el-form label-position="top" class="settings-form settings-grid"><el-form-item v-for="[key,label,hint,min,max,unit] in gatewayFields" :key="key" :label="label"><div class="parameter-input"><el-input-number v-model="form.gateway[key]" :min="min" :max="max" :precision="0" :aria-label="label+'（'+unit+'）'"/><span class="parameter-unit">{{unit}}</span></div><p class="field-hint">{{hint}}</p></el-form-item></el-form><el-collapse class="settings-form"><el-collapse-item title="高级调度参数" name="advanced"><el-form label-position="top" class="settings-grid"><el-form-item label="会话粘性"><div class="parameter-input"><el-input-number v-model="form.gateway.sticky_timeout" :min="1" :max="86400" :precision="0" aria-label="会话粘性"/><span class="parameter-unit">秒</span></div></el-form-item><el-form-item label="模型列表巡检间隔"><div class="parameter-input"><el-input-number v-model="form.gateway.health_check_interval" :min="0" :max="86400" :precision="0" aria-label="模型列表巡检间隔"/><span class="parameter-unit">秒</span></div><p class="field-hint">0 表示关闭，巡检不会发起生成请求。</p></el-form-item><el-form-item label="普通故障阈值"><div class="parameter-input"><el-input-number v-model="form.gateway.failure_threshold" :min="1" :max="100" :precision="0" aria-label="普通故障阈值（次）"/><span class="parameter-unit">次</span></div></el-form-item><el-form-item label="初始冷却时间"><div class="parameter-input"><el-input-number v-model="form.gateway.cooldown_seconds" :min="1" :max="3600" :precision="0" aria-label="初始冷却时间"/><span class="parameter-unit">秒</span></div></el-form-item></el-form></el-collapse-item></el-collapse><p class="field-hint">降低并发上限不会中断正在执行的请求。</p></el-tab-pane>
<el-tab-pane v-if="isSuper" label="向量服务" name="vector" lazy><div class="section-heading"><h2>向量服务</h2><p>为智能路由和内容合规提供共享的语义向量能力。</p></div><el-form label-position="top" class="settings-form" v-loading="auxiliaryLoading.vector"><el-form-item label="向量账号"><el-select v-model="form.vector.provider_id" :disabled="!auxiliaryReady.vector" filterable placeholder="选择已启用的向量账号" @change="form.vector.model='';vectorResult=null"><el-option v-for="p in providers" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item label="向量模型"><el-select v-model="form.vector.model" filterable :disabled="!form.vector.provider_id||!auxiliaryReady.vector" placeholder="选择账号下已启用的向量模型" @change="vectorResult=null"><el-option v-for="m in vectorModels" :key="m.model" :label="m.model+' → '+m.upstream_model" :value="m.model"/></el-select></el-form-item><el-empty v-if="auxiliaryReady.vector&&!providers.length" description="暂无可用向量账号"><router-link to="/admin/providers"><el-button type="primary">配置模型供应商</el-button></router-link></el-empty><el-alert title="更换服务后需手动重建已有样本向量" type="info" :closable="false">所有路由规则将使用新向量模型。保存不会触发调用；未配置共享服务时保留各路由原配置和本地内容合规向量。</el-alert><div class="section-actions"><el-button :loading="testLoading" :disabled="!savedVector.model||saving" @click="testVector">测试已保存的连接</el-button><router-link to="/admin/smart-route/samples">管理路由样本</router-link><router-link to="/admin/compliance/samples">管理审核样本</router-link></div><p v-if="currentDirty" class="field-hint">测试仅使用已保存配置，不包含当前未保存的修改。</p><p v-if="vectorResult" class="test-success">测试成功 · 向量维度 {{vectorResult.dimensions}} · <router-link :to="'/admin/call-logs/'+vectorResult.request_id">查看调用日志</router-link></p></el-form></el-tab-pane>


<el-tab-pane v-if="isSuper" label="Elasticsearch" name="elasticsearch" lazy><div class="section-heading"><h2>Elasticsearch</h2><p>将调用、管理审计日志及可选脱敏正文写入外部检索服务，支持 Elasticsearch 9.x。</p></div><div class="es-overview" v-loading="auxiliaryLoading.elasticsearch"><div><span>服务状态</span><strong>{{esStatus.unavailable?'状态不可用':esStatus.enabled?'已启用':esStatus.configured?'已配置，未启用':'未配置'}}</strong></div><div><span>当前队列</span><strong>{{esStatus.queue_count??'—'}} 条 / {{esStatus.queue_bytes??'—'}} 字节</strong></div><div><span>累计丢弃</span><strong>{{esStatus.dropped??'—'}}</strong></div><div><span>最近写入成功</span><strong>{{esStatus.last_success?formatDate(esStatus.last_success):'暂无'}}</strong></div><div><span>连续失败开始</span><strong>{{esStatus.failure_since?formatDate(esStatus.failure_since):'暂无'}}</strong></div></div><el-alert v-if="esStatus.last_error" :title="'最近错误：'+esStatus.last_error" type="warning" :closable="false"/><el-form label-position="top" class="settings-form"><div class="setting-line"><div><strong>启用外部日志</strong><p>关闭后停止写入，仅管理本应用专用日志索引。</p></div><el-switch v-model="form.elasticsearch.enabled" aria-label="启用 Elasticsearch"/></div><el-form-item label="Elasticsearch 地址"><el-input v-model="form.elasticsearch.url" placeholder="https://elasticsearch.example:9200"/></el-form-item><div class="settings-grid"><el-form-item label="认证方式"><el-select v-model="form.elasticsearch.auth_type"><el-option value="api_key" label="API Key"/><el-option value="basic" label="Basic Auth"/></el-select></el-form-item><el-form-item v-if="form.elasticsearch.auth_type==='basic'" label="用户名"><el-input v-model="form.elasticsearch.username" autocomplete="off"/></el-form-item></div><el-form-item :label="form.elasticsearch.auth_type==='basic'?'密码':'API Key'"><el-input v-model="form.elasticsearch.secret" type="password" show-password autocomplete="new-password" :placeholder="form.elasticsearch.secret_configured?'已加密保存，留空保留原值':'填写认证密钥'"/><p class="field-hint">变更地址或认证信息时须重新填写，已有密钥不会返回浏览器。</p></el-form-item><div class="settings-grid"><el-form-item label="请求正文上限（KiB）"><el-input-number v-model="form.elasticsearch.request_body_kib" :min="0" :max="16"/><p class="field-hint">0 表示不保存正文。</p></el-form-item><el-form-item label="响应正文上限（KiB）"><el-input-number v-model="form.elasticsearch.response_body_kib" :min="0" :max="16"/><p class="field-hint">正文始终脱敏，超出上限截断。</p></el-form-item><el-form-item label="外部保留天数"><el-input-number v-model="form.elasticsearch.retention_days" :min="1" :max="365"/></el-form-item></div><p class="field-hint">队列最多 1,000 条 / 8 MiB，满时丢弃新记录；失败保留重试。更换服务地址不会向新服务器发送旧队列数据。</p><div class="section-actions"><el-button :loading="testLoading" :disabled="saving" @click="testEs">测试已保存的连接</el-button><el-button @click="loadEsStatus">刷新状态</el-button></div><p v-if="currentDirty" class="field-hint">测试仅使用已保存配置，不包含当前未保存的修改。</p></el-form></el-tab-pane>
<el-tab-pane v-if="isSuper" label="系统状态" name="status" lazy><SystemStatus :active="tab==='status'"/></el-tab-pane>
